import re, collections
regions = collections.Counter(); mgrs=[]; years={}
meta={}
for f in files:
    w=f[8:11]; lines=open(f).read().splitlines()
    idx=next(i for i,l in enumerate(lines) if l.startswith('## Stock'))
    head=[l.strip() for l in lines[1:idx] if l.strip()]
    reg=None; man=None; yr=None
    for l in head:
        m=re.match(r'Region: (\w+)$', l)
        if m: reg=m.group(1)
        m=re.match(r'This site sits in the (\w+) region\.$', l)
        if m: reg=m.group(1)
        m=re.match(r'A (\w+)-region site\.$', l)
        if m: reg=m.group(1)
        m=re.match(r'Site manager: (.+)\.$', l)
        if m: man=m.group(1)
        m=re.match(r'Managed by (.+)\.$', l)
        if m: man=m.group(1)
        m=re.match(r'(.+) runs the floor here\.$', l)
        if m: man=m.group(1)
        m=re.match(r'(?:Opened in|Operating since|Commissioned) (\d+)\.$', l)
        if m: yr=int(m.group(1))
        for key,val in (('reg',reg),('man',man),('yr',yr)):
            pass
    meta[w]=(reg,man,yr)
    regions[reg]+=1
print(regions)
missing=[(w,m) for w,m in meta.items() if any(v is None for v in m)]
print('missing', missing)
print(sorted(set(m[2] for m in meta.values())))
print(len(meta))
# duplicates within stock
for f in files:
    w=f[8:11]
    if len(allw[w]) != len(set(allw[w])): print('dup',w)
for w in sorted(meta): print(w, meta[w])

