import re, collections
# independent region tally: count keyword occurrences per file
errs=[]
for f in files:
    t=open(f).read().lower()
    counts={r: len(re.findall(r'\b'+r+r'\b', t)) for r in ['north','south','east','west']}
    nz=[r for r,c in counts.items() if c]
    if len(nz)!=1: errs.append((f,counts))
print('region keyword ambiguity:', errs)
# stock lines: ensure exactly one quantity number per line
bad=[]
for f in files:
    w=f[8:11]; lines=open(f).read().splitlines()
    idx=next(i for i,l in enumerate(lines) if l.startswith('## Stock'))
    end=next(i for i,l in enumerate(lines) if l.startswith('## Notes'))
    body=[l.strip() for l in lines[idx+1:end] if l.strip()]
    if len(body)!=len(allw[w]): bad.append((w,'dup',body))
    for l in body:
        m=re.search(r'SKU-[A-Z]\d+', l)
        nums=re.findall(r'\d+', l.replace(m.group(0),''))
        if len(nums)!=1: bad.append((w,l))
print('stock line issues:', bad)
print('north list', sorted(w for w,m in meta.items() if m[0].lower()=='north'))
print('north count', sum(1 for m in meta.values() if m[0].lower()=='north'))
print(open('reports/w06.md').read())
print([ (w, meta[w][2]) for w in sorted(meta) ][:10])

